    // We penalize residuals that are non-zero but smaller than the minimum expected item size (approx 10)
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave residuals which are multiples of 
    // common divisors of the capacity (100: 20, 25, 50).
    if post_residual % 20 == 0 {
        score -= 15.0;
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Thresholding: If this is the last fitting bin, penalize the score to force 
    // consolidation unless the fit is near-perfect (Best-Fit principle).
    if fitting_bins_count == 1 && post_residual > 15 {
        score += 20.0;
    }

    // 5. New Bin Logic: If we are considering opening a new bin (bin_residual == bin_capacity),
    // only do so if the current open bins are all "bad" fits (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening new bins unless the density of existing bins is very low
        score += 60.0 - (open_bins_count as f64 * 2.0);
    }

    // 6. Global Progression: As we near the end of the stream, favor tighter packing 
    // to minimize the number of trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = post_res;

    // Penalty for creating a bin that is too sparse early in the stream, 
    // but allow flexibility as we approach the end of the stream.
    let sparsity_penalty = (1.0 - progress) * (bin_capacity as f64 - post_res).powi(2) / 20.0;
    score += sparsity_penalty;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy barrier 
    // to discourage opening it unless no other bin is a good fit.
    if bin_residual == bin_capacity {
        // Barrier is high but decreases as the stream progresses to allow packing 
        // efficiency to take over near the end.
        score += 35.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: if the next item is large, prioritize keeping space open.
    // If next_item_size is small, prioritize filling the current bin tightly.
    if next_item_size > 0 {
        let lookahead_impact = (next_item_size as f64 - post_res).abs().powf(1.5) * 0.1;
        if post_res < next_item_size as f64 {
            score += lookahead_impact;
        } else {
            score -= lookahead_impact * 0.5;
        }
    }

    // Encourage convergence toward the mean residual to maintain uniform bin fullness
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    // Penalize leaving a bin with "orphan" space that is likely too small for future items
    if post_res < 15.0 && post_res > 0.0 {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score to place item.
    // post_residual: The space left after placement.
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // Adding a slight non-linear weight to post_residual to discourage leaving large gaps.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Matching: Reward bins that create a post_residual close to the next_item_size.
    // This creates "perfect fit" potential for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 1.5;
    }

    // 3. Mean Residual Balancing: Penalize bins that deviate significantly from the average residual.
    // This maintains a uniform distribution of fill levels across bins.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.8;

    // 4. New Bin Threshold: Discourage opening a new bin unless the current fit is extremely poor.
    // If it's a new bin (residual == capacity), we set a high baseline cost.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting bins are forced to create very poor residuals.
        // We set the base cost of a new bin to be slightly higher than a "decent" fit.
        score = 65.0 - (open_bins_count as f64 * 0.1);
    } else {
        // If the bin is the last chance (fitting_bins_count == 1), prioritize it slightly 
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about fitting into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
