    // 3. Dynamic Pressure: Constrain late-game entropy
    let late_game_bias = (progress * 55.0).exp() * 0.52;
    score += (open_bins_count as f64).powf(1.78) * (1.22 + late_game_bias);

    // 4. Force selection on singular fits to prevent premature new bin usage
    if fitting_bins_count == 1 {
        score -= 420.0;
    }

    // 5. New Bin Gate: Dynamic thresholding based on remaining capacity
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalize new bins more if we are early in the stream
            score += 620.0 + (mean_residual * 3.8) + (progress * 410.0);
        } else {
            score -= 320.0;
        }
    }

    // 6. Density optimization: Reward exact fits and high-density buckets
    if post_residual == 0 {
        score -= 360.0;
    } else if post_residual > (bin_capacity * 65 / 100) {
        score -= 135.0;
    } else if post_residual % 12 == 0 {
        score -= 55.0;
    }

    // 7. Residual Variance management: Penalize deviation from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += (deviation * 1.62) * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    // 8. Lookahead-Residual Symmetry: Minimize pockets that trap future items
    if post_residual > 0 && post_residual < (next_item_size + 6) {
