    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Base score: punish large post_residuals (wasted space) quadratically to favor tight packing.
    // We add a penalty for opening new bins early in the stream, but allow them if the fit is perfect.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * post * 0.01;

    // Lookahead logic: if we can fit the next item in this bin, reduce the score.
    // If the current fit leaves space for the next item, we prioritize that bin.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalty for new bins: scale by progress to be more conservative as the stream nears the end.
    if is_new_bin {
        // New bins are penalized heavily unless they are the only option or the stream is ending.
        // We favor using existing bins (fitting_bins_count > 0) by adding a high constant.
        score += 40.0 + (progress * 20.0);

        // If it's the very last item, opening a new bin is neutral.
        if step_index == total_items - 1 {
            score -= 30.0;
        }
    } else {
        // If this bin is the only one that fits the current item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Penalize bins that deviate significantly from the mean residual to encourage uniformity.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor bins where the post_residual is a multiple of common item sizes (10, 20, 25).
    // This reduces the creation of "orphaned" gaps that cannot fit standard item sizes.
    let harmonic_penalty = (post_residual % 10) as f64 * 2.5;
    score += harmonic_penalty;

    // 2. Lookahead Synergy: If the next item can fit perfectly into the current post_residual,
    // strongly prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.5; 
    }

    // 3. Density Balancing: Penalize bins that deviate significantly from the mean residual
    // of all open bins to encourage uniform packing and prevent "bin starvation."
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate),
    // only choose it if the current best existing bin creates an extremely tight,
    // unusable space (e.g., < 5 units left, which is below the minimum item size).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin unless existing bins are very poor
            score += 45.0;
        }
    } else {
        // If it's an existing bin, favor "Best Fit" (minimize post_residual),
        // but discourage creating "sliver" gaps (1-9) which are hard to fill.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 5.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins
    // by being more aggressive with current fits to minimize remaining open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit typical future items 
    // (e.g., < 10) but not zero, it creates "unusable" space. We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining post_residual,
    // reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 20.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if we have plenty of open bins 
    // that could accommodate the current item, unless the fit is exceptionally good.
    if bin_residual == bin_capacity {
        // If it's a new bin, penalize based on current open bin count to prevent fragmentation.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // If it's an existing bin, reward it if it's the only one left that fits the item,
        // preventing the forced creation of a new bin later.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 4. Global Density Adjustment: As the stream progresses, favor tighter packing 
    // to handle potentially larger items later in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmentation" (small, unusable gaps)
    // If post_residual is small but > 0, it's often worse than leaving it empty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead: If next_item_size fits in the post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Bonus for a "perfect" fit for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if fits are poor.
        score += 30.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reward it for being "tight" relative to the current mean.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Progress-based scaling:
    // As we approach the end of the stream, prioritize closing gaps over opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    // 5. Fitting Constraint: 
    // If this is the only bin that can fit the item, heavily favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "slivers" (small, unusable residuals)
    // Residuals < 10 are generally bad unless it's a perfect fit (0)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead optimization: If next_item_size exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that can accommodate both current and next item
            score -= 15.0;
        }
    }

    // 3. Global state: If we are late in the stream, be more conservative with opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening new bins if there are existing bins available
        // Decrease penalty as the stream ends to clear out remaining items
        score += (80.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0);
    }

    // 4. Balance bin utilization: Penalize bins that deviate significantly from the mean_residual
    // This encourages keeping bins at similar fullness levels (Best-Fit-like behavior)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. If this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the score to ensure we don't open a new bin if we can avoid it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // We aim to minimize the score.
    // 1. Base cost: The post_residual (Best Fit principle).
    // 2. Penalty for creating "dead space": If post_residual is small but > 0, it's often better
    //    to pick a bin that leaves a larger, more usable remainder.
    // 3. Lookahead integration: If the next item fits into the current post_residual, 
    //    we prioritize this bin heavily.

    let mut score = post;

    // Penalty for "fragmentation": Small gaps that are hard to fill (e.g., 1-9 range).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead: Encourage placements that accommodate the next item.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 40.0 * (1.0 - progress.powf(0.5));
    }

    // Global state awareness: If we are late in the stream, be more aggressive about 
    // closing bins (lowering score for tight fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    // Penalize opening new bins early in the stream, but allow it if the fit is perfect.
    if bin_residual == bin_capacity {
        if post == 0.0 {
            score += 5.0; // Perfect fit in new bin is okay
        } else {
            score += 60.0 * (1.0 - (progress * 0.5));
        }
    }

    // Smooth coupling with mean_residual to prevent massive variance in bin usage.
    score += (post - mean_residual).powi(2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (slivers).
    // The "Best Fit" behavior is tempered by avoiding creating unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If the next item could fit perfectly into this bin's post_residual,
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 - diff).max(0.0);
    }

    // 3. Harmonic Class Logic: Normalize residual based on bin capacity.
    // We prefer keeping bins balanced around the mean_residual to avoid fragmentation.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // 4. Scarcity/Fitting Logic: If this is the only bin that can fit the item, 
    // it is highly valuable regardless of residual.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the residual of current 
    // open bins is extremely poor or the item is large.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already small,
        // suggesting that current bins are too tight to accommodate future items.
        if mean_residual > 20.0 {
            score += 15.0; 
        } else {
            score += 40.0; // Strong penalty for opening new bins prematurely
        }
    }

    // 6. Progression weighting: As we approach the end of the stream, 
    // prioritize fitting items into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Avoid creating small, unusable gaps.
    // If the post_residual is small but > 0, it's often a "poison" gap.
    // We heavily penalize gaps between 1 and 9 as they are likely too small for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open bin pressure: Penalize opening new bins unless necessary.
    // If we are looking at a new bin (bin_residual == bin_capacity), add a significant cost.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead optimization: If a future item exists, prioritize bins that 
    // leave enough space for the next item to potentially fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that will be too small for the immediate future item.
            score += 20.0;
        } else {
            // Reward bins that can accommodate both current and next items.
            score -= 10.0;
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the item, 
    // incentivize its selection to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global state normalization:
    // As the stream progresses, favor tighter packing to clear out bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin if other bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
    }

    // 2. Aggressive 2-step lookahead matching:
    // If next_item_size fits in post_residual, prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Reward tighter packing for the predicted next step
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Avoid creating "dead space":
    // If post_residual is too small for common items (e.g., < 10), it's often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Balance current bin against the global mean_residual:
    // If this bin is significantly emptier than the average, prioritize filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 20.0;
    }

    // 5. Last-chance penalty:
    // If this is the only bin that fits the current item, prioritize it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Progression dampening:
    // As the stream nears the end, be more conservative with bin usage (minimize new bins).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize small, "fragmented" residuals that are difficult to fill later
    // If post_residual is small but > 0, it creates "dead space" below the typical item size range.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead Integration: If the next item fits into the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (1.0 - progress);
    }

    // 3. Global State Balancing: If we have many open bins, prioritize tighter packing
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We should be very careful about opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins already
        score += 40.0 * (open_bins_count as f64 / 10.0).sqrt();
        // Exception: If we are near the end of the stream, opening a new bin is less harmful
        score -= 20.0 * progress;
    } else {
        // If we are placing in an existing bin, reward bins that align with the global mean
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Dynamic threshold for "Best Fit" behavior
    // If the item fits perfectly, strongly prioritize it
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize new bin creation heavily, scaling with progress to allow more flexibility early on
    if is_new_bin {
        score += 15.0 + (35.0 * progress.powi(2));
    } else {
        // Non-linear coupling: penalize small, awkward residuals that cannot fit common future items
        // We reward bins that leave space closer to the expected next item size
        let residual_fit_error = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            post_residual as f64
        };

        score += residual_fit_error * 0.2;

        // If this is the only bin that can fit the item, favor it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Discourage creating high fragmentation relative to the mean of other bins
        let fragmentation_penalty = (post_residual as f64 - mean_residual).powi(2) * 0.05;
        score += fragmentation_penalty;
    }

    // Favor bins that are already partially filled to pack them tighter
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space that is too small for common items (below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit Decreasing logic: Favor bins that leave the least space (lower post_residual)
    // We already start with post_residual, which inherently favors tightest fit.

    // Harmonic Class logic: Penalize residuals that don't align well with potential future items
    // If next_item_size is known, reward bins where post_residual is close to next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // Dynamic Thresholding: If we have many open bins, penalize opening new ones significantly
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // High penalty for opening a new bin if we have existing capacity
            score += 85.0 + (mean_residual * 0.5);
        } else {
            // First bin is always free
            score = 0.0;
        }
    } else {
        // If it's a fitting bin, reward it if it's the only option or a very tight fit
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Penalize bins that deviate significantly from the mean residual of current open bins
        // This encourages "leveling" the fill levels of active bins
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Progress-based scaling: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space" (gaps too small to fit common items).
    // If the post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Prioritize filling bins to maintain a low open_bins_count.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead heuristic: If the next item can fit in this post_residual, reward the placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. If this is the only bin that can fit the item, prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Dynamic pressure: As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin when existing bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // Lookahead: If next_item_size is known, favor bins that can accommodate it.
    // If post_residual is close to next_item_size, we create a "tight" match.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly
            let diff = (post_residual - next_item_size) as f64;
            score -= (20.0 - diff).max(0.0);
        } else {
            // Penalize bins that render the next item impossible to place here
            score += 15.0;
        }
    }

    // Adaptive threshold: If we are late in the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;

    // If we are forced to pick a bin (only one fits), prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Penalty for leaving "fragmented" bins (residual too small for common items)
    // Avoid leaving residuals between 1 and 9 as they are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Favor bins that stay near the mean_residual to keep occupancy balanced
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
