    // 1. Dynamic Thresholding: Penalize small "fragmentation" gaps more aggressively as the stream progresses.
    // Small gaps (1-15) are hard to fill; reward bins that leave larger, more versatile gaps.
    if post_residual > 0 && post_residual <= 15 {
        score += 32.0;
    }

    // 2. Lookahead Synergy: If the next item is large, favor bins that can accommodate it.
    // We increase the reward for bins that can fit the next item based on its size relative to the capacity.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (20.0 + (next_item_size as f64 * 0.2));
        } else if fitting_bins_count > 0 {
            // Strong penalty for blocking the next item if better alternatives exist.
            score += 18.0;
        }
    }

    // 3. New Bin Control: Use a non-linear cost function to discourage new bins.
    // Penalty scales with open_bins_count to prevent excessive spreading.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if current fits are extremely inefficient.
            score += 55.0 + (open_bins_count as f64 * 0.5);
        } else {
            // If forced to open a new bin, neutralize the base residual penalty.
            score -= 12.0;
        }
    }

    // 4. Density Optimization: Favor "Golden" residuals (multiples of 25) which are high-probability fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 5. Global Compaction: Near the end of the stream, aggressively close bins.
    // Penalize the count of open bins to force consolidation before the stream terminates.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.75 {
        score += (open_bins_count as f64) * 4.5;
    }

    // 6. Mean-Residual Balancing: Avoid bins that deviate significantly from the mean_residual.
    // This helps keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

