pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large gaps (dead space).
    // The lower the post_residual, the better the fit.
    // We penalize small post_residuals only if they are too small to fit potential future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Integration:
    // If next_item_size fits in the current post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State Awareness:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // bins are already open to discourage fragmentation early.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (progress * 15.0);
    }

    // 4. Scarcity/Bottleneck Logic:
    // If this is the only bin that can fit the item, we are forced to use it.
    // We make this choice very attractive to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic Thresholding:
    // As the stream nears completion, become more aggressive about closing bins (minimizing residuals).
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Mean Residual Balancing:
    // If this bin's residual is significantly better than the global mean, favor it.
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a non-linear scaling of the residual to prioritize tight fits
    // Squaring the post_residual penalizes large gaps exponentially
    let mut score = (post_residual as f64).powf(1.15);

    // 1. Dynamic Lookahead: Stronger bias towards accommodating the next item
    // We reward bins that leave enough space for the next item, but penalize
    // wasting space if the next item is small.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0 + (next_item_size as f64 * 0.2);
        } else if post_residual > 0 {
            score += 18.0;
        }
    }

    // 2. Dead Space Mitigation: Identify "micro-gaps" that are unlikely to be filled.
    // If post_residual is small but not zero, it's often a liability.
    if post_residual > 0 && post_residual < 12 {
        score += 30.0;
    }

    // 3. New Bin Thresholding: Sophisticated cost function for opening new resources.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;
        // If we are nearing the end of the stream, avoid opening new bins at all costs.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
        // If existing bins are already efficient (low mean_residual), penalize opening new ones.
        if mean_residual < (bin_capacity as f64 * 0.3) {
            score += 20.0;
        }
    }

    // 4. Harmonic Alignment: Favor "perfect" completions (zero residual)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    }

    // 5. Global Load Balancing: Prevent proliferation of too many open bins
    // This acts as a soft constraint on open_bins_count.
    score += (open_bins_count as f64).sqrt() * 5.0;

    // 6. Adaptive Penalty for "tight" bins
    // If the bin is getting very full, it becomes a high-value target to complete.
    if bin_residual < 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the primary goal: minimize wasted space (post_residual).
    let mut score = post_residual as f64;

    // 1. Adaptive Dead-Space Penalty:
    // Small residuals are toxic unless they are 0. Scale penalty by the mean_residual
    // to adapt to the current distribution of item sizes.
    if post_residual > 0 {
        if (post_residual as f64) < (mean_residual * 0.35) {
            score -= 14.0; // Strong reward for tight, efficient fits
        } else if post_residual < 22 {
            score += 28.0; // Heavy penalty for "unusable" small gaps
        }
    }

    // 2. Lookahead Synergy:
    // Anticipate the next item. If the bin can fit it, prioritize it significantly.
    // If it cannot fit, add a penalty that scales with the bin's current fullness.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (22.0 + (next_item_size as f64 * 0.15));
        } else {
            score += 18.0; 
        }
    }

    // 3. New Bin Gate (The "Consolidation" Logic):
    // Heavily resist opening new bins. If fitting_bins_count > 0, the penalty for
    // a new bin must be high enough to force packing into existing, even suboptimal, slots.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / total_items as f64;
            // Increase resistance as we progress to avoid fragmenting the end-stream
            score += 65.0 + (progress * 50.0);
        } else {
            score -= 12.0; // Only open if no other choice exists
        }
    }

    // 4. Harmonic Alignment:
    // Favor residuals that are multiples of 25 (common capacity factors).
    // This maintains "bin health" by keeping remaining space usable for standard items.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. Global Consolidation Pressure:
    // Late-stage compaction: If we are near the end of the stream, 
    // penalize the number of open bins to force items into the fewest possible containers.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.75 {
        score += (open_bins_count as f64) * 6.5;
    } else if progress < 0.15 {
        // Early stage: focus on absolute fit quality to avoid early bloat
        score += (fitting_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'dead' zone that cannot fit likely future items.
    // If post_residual is small (e.g., < 10), it's either a perfect fit or unusable space.
    if post < 10.0 && post > 0.0 {
        score += 25.0; 
    }

    // Lookahead logic: If the next item is large, prioritize keeping larger residuals.
    // If next_item_size is 0, we are near the end of the stream; prioritize packing tightly.
    if next_item_size > 0 {
        let next_item_penalty = (next_item_size as f64 - post).max(0.0) * 0.5;
        score += next_item_penalty;
    }

    // Dynamic threshold: As the stream progresses, we become more conservative about 
    // opening new bins. If fitting_bins_count is 1, we are at a critical decision point.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the current open_bins_count and progress to discourage
    // fragmentation early on, but allow it if open_bins_count is low.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress) + (open_bins_count as f64 * 2.0);
    }

    // Coupling mean_residual to balance the bin space globally.
    // If this bin's post_residual is much lower than the mean, it's a "tight" bin.
    score += (post - mean_residual).powi(2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a base score weighted towards Best Fit (post_residual)
    let mut score = post_residual as f64;

    // 1. Dynamic Lookahead Integration:
    // Heavily incentivize bins that can accommodate the next item to keep the bin count low.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward high-fit-probability bins; subtract more as we approach the end
            score -= (25.0 + (step_index as f64 / total_items as f64) * 15.0);
        } else {
            // Penalize bins that would "orphan" the next item
            score += 20.0;
        }
    }

    // 2. Anti-Sliver Heuristic:
    // Small residuals (1-15) are mathematically problematic for random item streams.
    // Penalize them unless they are zero (perfect fit).
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 3.5;
    }

    // 3. Harmonic Packing:
    // Favor residuals that align with common factor clusters (20, 25, 33, 50).
    if post_residual > 0 {
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 8.0;
        }
    }

    // 4. Entropy Control:
    // Penalize bins that deviate from the mean residual to prevent "bin starvation,"
    // but allow wider variance in the first 20% of the stream to establish diversity.
    if step_index > (total_items / 5) {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.15;
    }

    // 5. New Bin Candidate Logic:
    // The "New Bin" call occurs when bin_residual == bin_capacity.
    // Only open a new bin if the existing bins are poor fits (post_residual > 40).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin unless existing options are "ugly"
            score += 55.0;
        } else {
            // Neutralize the baseline score for the mandatory new bin
            score -= 10.0;
        }
    }

    // 6. Global Compaction Pressure:
    // As the stream concludes, exponentially increase the cost of keeping bins open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.75 {
        score += (open_bins_count as f64) * 1.5 * (progress * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (1..9) that is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic coupling: If next_item_size is large (e.g., > 50), favor bins that leave enough room.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that are perfectly sized for the predicted next item.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Pressure management: If many bins are open, aggressively try to pack into existing ones.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 0.2;
    }

    // 4. Efficiency threshold: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Penalize opening a new bin unless the current mean_residual is very high (indicating poor packing).
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.3);
    }

    // 6. Modulo-based "harmonic" alignment: Reward leaving space that is a multiple of common item sizes (20, 25).
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

