    // Penalize gaps that are too small to hold common items (below 25)
    // but reward perfect fits heavily to encourage tight packing.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual < 25 {
        score += 32.0;
    }

    // 2. Adaptive Lookahead Coupling
    // Use the next_item_size to dynamically adjust the cost of the current fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for "chaining" fits (keeping bin viable for next item)
            score -= 22.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize "stranded" space that cannot fit the next item
            score += 18.0;
        }
    }

    // 3. New Bin Thresholding (The "Empty Bin" Decision)
    // Use the ratio of open bins to total progress to prevent premature proliferation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the average residual is currently high,
            // otherwise, force usage of existing bins to maximize density.
            score += 65.0 + (mean_residual * 0.5);
        } else {
            score -= 12.0;
        }
    }

    // 4. Harmonic Pressure (Refined)
    // Favor residuals that align with the capacity/4 to maximize potential for future items.
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 5. Global Compaction Pressure
    // As the stream progresses, increase the cost of maintaining too many open bins.
    // This forces the algorithm to "close" bins by filling them completely.
    if open_bins_count > 0 {
        let utilization_pressure = (open_bins_count as f64 / (step_index as f64 + 1.0).sqrt()) * 5.0;
        score += utilization_pressure * progress;
    }

    // 6. Variance Reduction
    // Penalize extreme deviations from the mean to keep bin levels balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

