    // We penalize this heavily to encourage packing that leaves either 0 or >= 10 space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins, but scale based on progression.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) * (1.0 - (step_index as f64 / total_items as f64));
    }

    // 3. Lookahead Synergy: If the next item can fit into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 * 0.8);
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Residual Balancing: If the current post_residual is significantly lower than the mean_residual
    // of other bins, it indicates a tighter, more efficient fit.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
