    // Reward residuals that are multiples of 25 (e.g., 25, 50, 75) as they are the most flexible
    // for packing common item sizes (100, 50, 25, 20).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 8.0;
    }

    // 5. Residual Variance Control:
    // Penalize if the current bin's residual deviates significantly from the mean_residual.
    // This keeps the bins relatively balanced in their fill levels.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common items (10-30)
    // but too large to be considered "full".
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - (post_residual as f64 * 2.0);
