    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Control: Penalize bins that create an awkward residual relative to mean_residual.
    // If we have many open bins, we want to consolidate (prefer smaller post_residual).
    if open_bins_count > 5 {
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // 4. New Bin Thresholding: Discourage opening new bins unless the fit is perfect or necessary.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only pick new bin if we have many bins already and this is a "clean" fit 
        // or if fitting_bins_count is low (to avoid creating a new bin when we could use an existing one).
        score += 35.0; 
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 5. Progress weighting: As the stream nears the end, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && !is_new_bin {
        score -= (100 - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the base cost: the remaining capacity in the bin.
    // Lower post_residual is better, favoring "Best Fit".
