    // 1. Refined Dead Space Penalty:
    // Small residuals (1-18) are often unusable "dead zones" unless they are zero.
    // We penalize these to force items into bins that leave larger, more flexible gaps.
    if post_residual > 0 && post_residual < 19 {
        score += 26.0;
