    // 2. Adaptive Lookahead:
    // If the next item is large, we prioritize bins that can accommodate it.
    // We scale this reward by the item size to prioritize the most critical fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (18.0 + (next_item_size as f64 * 0.25));
        } else if post_residual > 0 {
            // Penalize bins that "block" the next item.
            score += 12.0;
        }
    }

    // 3. New Bin Gate (The "Fragmentation Resistance"):
    // Heavily penalize opening a new bin if existing bins are capable of fitting.
    // The penalty increases as the stream progresses to discourage late-stage fragmentation.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 55.0 + (progress * 40.0) + (open_bins_count as f64 * 0.8);
        } else {
