            score -= 8.0;
        }
    }

    // 4. Harmonic Alignment:
    // Favor residuals that align with common bin capacity fractions (20, 25, 50).
    // This maintains "clean" headroom for future items.
    if post_residual == 0 {
        score -= 22.0;
    } else if post_residual % 25 == 0 || post_residual % 20 == 0 {
        score -= 14.0;
    }

    // 5. Global Pressure / Density Control:
    // Near the end of the stream, aggressively consolidate to close open bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score += (open_bins_count as f64) * 6.0;
    } else if progress < 0.20 {
        // Early stream: be more flexible to allow better future packing density,
        // specifically favoring bins that have already been partially filled.
        score -= (fitting_bins_count as f64) * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
