        }
    }

    // 4. Harmonic Alignment:
    // Prioritize residuals that allow future packing flexibility (multiples of 25/50).
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual % 25 == 0 {
        score -= 28.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // 5. Global Entropy Management:
    // Shift pressure: early-stage prioritize filling "half-full" bins to reduce active count.
    // Late-stage: aggressively penalize new bin creation by factoring in open_bins_count.
    let progress = step_index as f64 / total_items as f64;
