    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large empty spaces (waste) heavily.
    // As the stream progresses, become more aggressive about packing tightly (Best Fit-like behavior).
    // The term (post * (1.0 + progress)) prioritizes bins where the resulting gap is minimized.
    let mut score = post * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with the number of open bins and the ability to fit the item elsewhere.
    // This discourages opening new bins unless the existing ones are very poor fits.
    if bin_residual == bin_capacity {
        score += 85.0 + (open_bins_count as f64 * 2.5) + (fitting_bins_count as f64 * 15.0);
    } else {
        // If the bin is already open, penalize based on how much the residual deviates from 
        // the mean residual of all open bins (encourages uniform filling).
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead heuristic: If the next item exists, penalize placements that
        // leave a gap smaller than the next item if possible, 
        // or reward placements that leave exactly enough space for the next item.
        if next_item_size > 0 {
            if post < next_item_size as f64 {
                // If next item cannot fit, add a penalty proportional to the tightness 
                // to discourage stranding small gaps.
                score += 15.0 * (1.0 - (post / next_item_size as f64));
            } else if post >= next_item_size as f64 && post < (next_item_size as f64 + 10.0) {
                // Reward placements that leave a perfect or near-perfect fit for the next item.
                score -= 20.0;
            }
