    // 5. Global Packing Pressure
    // Adapt to the stream phase: 
    // Early phase: Pack tight (low bin count). Late phase: Clear bins (minimize open count).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.90 {
        // Late game: Aggressively prefer bins with smaller residuals to finish them off
        score -= (post_residual as f64) * 0.8;
        score += (open_bins_count as f64) * 20.0;
    } else if progress < 0.15 {
        // Early game: Prefer bins that already contain items to keep 'active' count low
        if bin_residual < (bin_capacity / 2) {
