    // If we have few open bins, prioritize keeping the mean residual high to allow flexibility.
    let occupancy_factor = (open_bins_count as f64) / 10.0;
    score += (mean_residual - post_res) * occupancy_factor;

    // New-bin gate:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Make opening a new bin expensive early on, but cheaper as the stream progresses 
    // and we have a high number of open bins (to prevent fragmenting existing bins).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
