    // Lower post_residual means the bin is tighter, which is generally better.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // We penalize new bins significantly, but reduce this penalty as the stream nears the end
        // to ensure we don't end up with many nearly-empty bins at the very end of the stream.
        score += 45.0 * (1.0 - (progress * 0.5));

        // If there are other bins that could fit the item, opening a new one is highly discouraged.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // For existing bins, we favor placements that leave the bin residual close to the
        // expected size of future items (next_item_size) or the current mean residual.
        // This promotes a "Best-Fit" behavior while considering lookahead.
        let target_residual = if next_item_size > 0 { next_item_size as f64 } else { mean_residual };
