        score += deviation * 0.5;

        // If this is the last bin that can fit the item, we lower the score to prioritize
        // filling the bin before potentially opening a new one later.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Adjust score based on the density of open bins.
    // Higher open_bins_count makes us more aggressive in filling existing bins.
    score += (open_bins_count as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
