    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive Density:
    // Penalize small "dead zones" (1-18) more harshly to avoid tiny gaps.
    // Reward residuals that keep bins near the mean_residual to maintain entropy balance.
    if post_residual > 0 {
        if post_residual < 19 {
            score += 52.0; 
        } else {
            let drift = (post_residual as f64 - mean_residual).abs();
            score -= drift * 0.15;
        }
    }

    // 2. Lookahead Optimization:
    // Strengthened reward for accommodating next_item_size to reduce cross-bin fragmentation.
    // Use the scarcity of fitting bins to aggressively protect capacity for upcoming items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let scarcity_bonus = if fitting_bins_count < 3 { 35.0 } else { 12.0 };
            score -= (55.0 + (next_item_size as f64 * 0.8) + scarcity_bonus);
        } else if post_residual > 0 {
            score += 45.0; // Stricter penalty for blocking next_item_size
        }
    }

    // 3. New Bin Gate:
    // Increased penalty for opening new bins when space is available.
    // Added a non-linear scaling factor to discourage "bin sprawl" as the stream progresses.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0 + (progress * 150.0) + (open_bins_count as f64 * 4.5) + (open_bins_count.pow(2) as f64 * 0.05);
        } else {
            score -= 90.0; // Aggressive reward for creating a new bin when forced
        }
    }

    // 4. Harmonic Alignment:
    // Prioritize clean residuals. Exact fits (post_residual == 0) are the highest priority.
    if post_residual == 0 {
        score -= 85.0;
    } else if post_residual % 25 == 0 {
        score -= 35.0;
    } else if post_residual % 20 == 0 {
        score -= 18.0;
    }

    // 5. Global Pressure:
    // Early-stage: favor packing into bins that are already partially full to minimize the "active" bin count.
    // Late-stage: apply heavy consolidation pressure to prevent trailing empty space.
    if progress > 0.85 {
        score += (open_bins_count as f64) * 45.0;
    } else if progress < 0.25 {
        if bin_residual < (bin_capacity / 2) {
            score -= 30.0; 
        }
    }

    // 6. Dynamic Efficiency Penalty:
    // Penalize high open_bins_count relative to total_items to force tighter packing
    // across the entire lifecycle of the bin stream.
    if open_bins_count > (total_items / 10) {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let bin_res = bin_residual as f64;
    let item = item_size as f64;
    let next_item = next_item_size as f64;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    // We penalize larger post_residuals quadratically to consolidate space.
    let mut score = post_res.powf(1.8);

    // Lookahead coupling: If next_item can fit into current post_residual, 
    // prioritize this bin to prevent fragmentation.
    if next_item > 0.0 && next_item <= post_res {
        score -= (next_item / 100.0) * 500.0;
    }

    // Dynamic Penalty: As the stream nears the end (progress -> 1.0), 
    // aggressively penalize opening new bins by increasing the cost of 
    // empty bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 150.0 + (progress * 300.0);
        score += new_bin_penalty;
    }

    // Mean Residual Balancing: penalize bins that deviate significantly 
    // from the current mean residual to keep bin levels uniform.
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.5;

    // Scarcity factor: If this is the only bin that can fit the item, 
    // heavily incentivize choosing it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Adaptive capacity threshold: discourage very small post_residuals that 
    // create "unfillable" gaps (e.g., < 10) unless it's the end of the stream.
    if post_res < 10.0 && post_res > 0.0 {
        score += (10.0 - post_res) * (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tightest fit (Best Fit)
    let mut score = post_res;

    // 1. Dynamic Thresholding:
    // Penalize small "sliver" residuals that are unlikely to accommodate future items.
    // Increase strictness as the stream progresses.
    if post_residual > 0 && post_residual < 20 {
        score += (22.0 - post_res) * (1.1 + progress * 1.5);
    }

    // 2. Lookahead Coupling:
    // If next_item_size fits in the post_residual, heavily reward this bin to keep it "active".
    // If it doesn't fit, apply a penalty scaled by how much capacity is wasted.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0 + (next_item_size as f64 * 0.35);
        } else if post_residual > 0 {
            score += 18.0 + (next_item_size as f64 - post_res) * 0.25;
        }
    }

    // 3. New-Bin Gate (The "Opening" Logic):
    // Use an exponential growth penalty for open_bins_count to force consolidation.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage new bin if existing ones work, with late-game urgency.
            score += 110.0 + (progress * 80.0) + (open_bins_count as f64 * 3.5);
        } else {
            // If we MUST open, subtract to make it the least bad option.
            score -= 45.0;
        }
    }

    // 4. Harmonic Alignment:
    // Reward "clean" cuts that leave round-number residuals (multiples of 10),
    // which are statistically more likely to fit standard item distributions.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    }

    // 5. Global Pressure:
    // During mid-stream, favor filling bins that are already below 50% capacity
    // to prevent creating many half-empty, inefficient bins.
    if progress > 0.1 && progress < 0.9 {
        if bin_residual < (bin_capacity / 2) {
            score -= 10.0;
        }
    }

    // Final check: if we have too many open bins, penalize non-optimal fits
    if open_bins_count > 50 {
        score += post_res * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a heavy penalty based on existing open bin efficiency.
    // We only open a new bin if the best fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        // Penalty is proportional to how much space we are wasting by not using existing bins.
        // We favor opening a new bin only when open bins are already very full.
        score += (open_bins_count as f64 * 15.0) + (mean_residual * 0.5);
        return score;
    }

    // 2. Harmonic/Modulo logic: penalize post-residuals that create "useless" small gaps.
    // A gap of 1-9 is often a "dead zone" for items 10-80.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If the current post_residual cannot fit the next item, penalize this choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it strongly to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. Fill density bias: Favor filling bins to be as full as possible (Best Fit variant).
    // We want the post_residual to be as small as possible, so we subtract a factor 
    // of the post_residual to make it even more attractive to choose tight fits.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
