        } else if post_residual > 0 {
            score += 32.0;
        }
    }

    // 3. New Bin Gate:
    // Refined quadratic penalty to curb fragmentation as bin count grows.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
