        } else {
            score -= 30.0;
        }
    }

    // 4. Structural Alignment:
    // Favor modular residuals to keep bins useful for common item sizes.
    if post_residual == 0 {
        score -= 52.0;
    } else if post_residual % 25 == 0 {
        score -= 26.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // 5. Global Pressure:
    // Tighten packing in the final 15% of the stream.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score += (open_bins_count as f64) * 22.0;
    } else if progress < 0.25 {
        // Early phase: prefer filling empty bins to establish a "baseline" bin set.
        if bin_residual < (bin_capacity / 2) {
            score -= 18.0;
        }
    }

    // 6. Entropy Mitigation:
    // Penalize bins that deviate significantly from the mean_residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
