            score -= (36.0 + (next_item_size as f64 * 0.5) + scarcity_bonus);
        } else {
            score += (34.0 - (post_residual as f64 * 0.2));
        }
    }

    // 3. New Bin Gate (The "Fragmentation Barrier"):
    // Heavily penalize opening a new bin if the current bin pool has high capacity.
