        } else {
            score -= 35.0; // Essential new bin
        }
    }

    // 4. Harmonic Alignment:
    // Favor exact fits and larger remainder thresholds (multiples of 25) 
    // to reduce fine-grained fragmentation.
    if post_residual == 0 {
        score -= 52.0;
    } else if post_residual % 25 == 0 {
        score -= 24.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // 5. Global Pressure (Late-stage consolidation):
