}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps too small for any likely future item).
    // Given range 10-80, gaps < 10 are highly likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Prioritize filling bins that are already "half-full" to keep open_bins_count low.
    // We reward placements that bring the bin_residual closer to the mean_residual of other bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // 3. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Pressure: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0;

        // If there are existing bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Extreme fit: Reward perfect fit (residual 0) strongly.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

