    } else if post_residual % 25 == 0 {
        score -= 28.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // 5. Global Pressure:
    // Dynamic consolidation: late-stage bins are penalized to force full packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score += (open_bins_count as f64) * 45.0;
    } else if progress < 0.15 {
        // Early-stage: prefer filling bins that are already active, rather than spreading out.
        if bin_residual < (bin_capacity * 3 / 4) {
            score -= 30.0;
        }
    }

    // 6. Residual Variance Control:
    // Penalize extreme deviations from mean_residual to prevent outliers.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.35;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor smaller post_residuals (tighter packing)
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Integration: If next_item_size is large, avoid small post_residuals
    // that might trap the next item. If next_item_size fits in current post_residual,
    // we prioritize that specific bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else if post_residual > 0 && post_residual < 20 {
            // Penalty for creating "slivers" that are too small for common items
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: Dynamic control of opening new bins
    // As the stream progresses, we become more conservative (penalize new bins)
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        let mut new_bin_cost = 45.0 + (progress * 20.0);

        // If we have many fitting bins, opening a new one is highly inefficient
        if fitting_bins_count > 0 {
            new_bin_cost += (fitting_bins_count as f64) * 10.0;
        }
        score = new_bin_cost;
    }

    // 4. Global State Balancing: Use mean_residual to prevent uneven bin utilization
    // If the current bin is significantly "fuller" than the average, we prefer it.
    if bin_residual < bin_capacity {
        let deviation = bin_residual as f64 - mean_residual;
        score -= deviation * 0.2;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

