pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    // We penalize larger post_residuals quadratically to favor tight packing.
    let mut score = post_res.powf(1.5);

    // Lookahead interaction:
    // If a next item exists, penalize bins that leave a residual smaller than the next item
    // but larger than zero, as this creates "fragmentation" (dead space).
    if next_item_size > 0 {
        if post_res < next_item_size as f64 && post_res > 0.0 {
            score += (next_item_size as f64 - post_res) * 2.5;
        }
    }

    // Progression coupling:
    // As the stream nears the end, become more aggressive in filling existing bins 
    // to avoid leaving trailing empty bins.
    let exhaustion_factor = 1.0 - progress;
    score += (open_bins_count as f64) * exhaustion_factor * 5.0;

    // Penalty for opening a new bin:
    // Only open a new bin if the current post_residual of the best existing bin 
    // is significantly worse than the potential of a fresh bin.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only return a low score if the average residual is already very high (bad packing)
        // or if no bins can fit the current item (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            // Must open a new bin if nothing fits.
            score = -100.0;
        }
    } else {
        // Existing bin logic:
        // Bias towards bins that are already "half-full" to keep future options open.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
