    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / total_items as f64;
            let complexity = (open_bins_count as f64).ln() * 12.0;
            score += 110.0 + (progress * 75.0) + (open_bins_count as f64 * 1.8) + complexity;
        } else {
            score -= 35.0; // Only open new if no other choice
        }
    }

    // 4. Harmonic Alignment:
    // Focus on alignment that creates "clean" multiples of 20, which is the most frequent 
    // divisor in common item distributions.
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual % 20 == 0 {
        score -= 28.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
