    // 5. Global Pressure & State Balancing:
    // Use the mean_residual as a dynamic anchor to prevent local clustering.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.90 {
        score += (open_bins_count as f64) * 22.0;
    } else {
        // If current bin residual is significantly above mean, discourage adding more
        if (bin_residual as f64) > (mean_residual * 1.4) {
            score += 8.0;
        } else if (bin_residual as f64) < (mean_residual * 0.6) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
