        // preventing the accumulation of highly fragmented bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Threshold sensitivity: if this is the last fitting bin, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
