            score += 32.0; // Penalize "blocking" the next item
        }
    }

    // 3. New Bin Gate:
    // Controls the cost of opening a new bin. 
    // Increased penalty for late-stage bin opening to force consolidation.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 115.0 + (progress * 85.0) + (open_bins_count as f64 * 3.2);
        } else {
            score -= 35.0; // Essential new bin, reward opening
        }
    }

    // 4. Harmonic & Geometric Alignment:
    // Favor residuals that align with common item size distributions (multiples of 20, 25, 33).
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual % 25 == 0 {
        score -= 24.0;
    } else if post_residual % 20 == 0 {
        score -= 18.0;
    } else if post_residual % 33 == 0 {
        score -= 12.0;
    }

    // 5. Global Pressure & Variance Control:
    // Use the mean_residual to influence the "balance" of the bin pool.
    // If current bin residual is significantly above mean, penalize slightly to force uniform filling.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.90 {
        score += (open_bins_count as f64) * 22.0; // Aggressive closure
    } else if progress < 0.15 {
        if bin_residual < (bin_capacity / 2) {
            score -= 16.0; // Fill early bins to capacity
        }
    }

    // Variance dampening: penalize bins that deviate too far from the average residual
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += (residual_diff * 0.08);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // We prioritize bins that leave the smallest residual (Best Fit),
    // but penalize creating "fragmented" space (small remainders) that cannot fit future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

