        }
    }

    // 2. Lookahead optimization:
    // If the next item is large, avoid creating a residual that is slightly too small for it.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Penalize creating "dead space" that cannot fit the next item
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward creating a residual that fits the next item perfectly (Exact Fit)
        if post_residual == next_item_size {
            score -= 15.0;
        }
