    // Scaling by 0.9 to flatten the influence of raw residual against complex heuristics.
    let mut score = post_residual as f64 * 0.9;

    // 1. Adaptive Density:
    // Focus on closing bins (low residual) vs keeping them flexible.
    if post_residual > 0 {
        if post_residual < 16 {
            score += 48.0; // Penalty for fragmenting small space
        } else if (post_residual as f64) < (mean_residual * 0.65) {
            score -= 32.0; // Reward high-density filling
        }
    }

    // 2. Lookahead Optimization:
    // Enhanced lookahead using relative fitting pressure.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item, adjusted by current scarcity.
            let scarcity_bonus = (open_bins_count as f64 / (fitting_bins_count as f64 + 1.0)) * 22.0;
            score -= (58.0 + (next_item_size as f64 * 0.75) + scarcity_bonus);
        } else if post_residual > 0 {
            // High penalty for blocking the next item
            score += 55.0; 
        }
    }

    // 3. New Bin Gate:
    // Logistic-curve growth for new bin penalty to prevent early-game bloat.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / total_items as f64;
            let density_pressure = (open_bins_count as f64).powf(1.25) * 4.5;
            score += 140.0 + (progress * 110.0) + density_pressure;
        } else {
            score -= 95.0; // Critical requirement to open if no fit
        }
    }

    // 4. Harmonic Alignment:
    // Encourage clearing bins (0 residual) and maintaining large headroom.
    if post_residual == 0 {
        score -= 90.0;
    } else if post_residual % 25 == 0 {
        score -= 38.0;
    } else if post_residual > (bin_capacity / 2) {
        score -= 15.0; // Favor keeping large headroom for future large items
    }

    // 5. Global Pressure:
    // Sigmoid ramp to force consolidation in the final 20% of the stream.
    let progress = step_index as f64 / total_items as f64;
    let late_game_multiplier = 1.0 / (1.0 + (-(progress - 0.80) * 25.0).exp());
    score += (open_bins_count as f64) * 48.0 * late_game_multiplier;

    // 6. Residual Variance Control:
    // Penalize deviation from the mean_residual to prevent extreme bin states.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22;

    score
}

