    // 1. Penalize fragmentation: If the post_residual is too small to fit common items (10-20),
    // it creates "dead space". We penalize residuals in the [1, 19] range heavily.
    if post_residual > 0 && post_residual < 20 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Harmonic Class/Lookahead coupling: If a next item exists, try to leave space for it.
    // If the current placement leaves a hole that fits the next item perfectly (or close to it),
    // reward that specific bin.
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Perfect fit reward
            score -= 40.0 * (1.0 / (diff as f64 + 1.0));
        } else {
            // If it can't fit the next item, penalize slightly based on how much it misses
            score += 5.0;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the current state of open bins is very crowded (high mean_residual is bad,
    // but here we want to balance the number of bins).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin: high enough to favor existing bins, 
        // but low enough to allow it if existing bins are all "bad" fits.
        score += 35.0;

        // If we are at the end of the stream, penalize opening new bins more.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Harmonic packing: Favor bins that leave a residual that is a multiple of 10,
    // as these are statistically more likely to accommodate future items in uniform distributions.
    let remainder = post_residual % 10;
    score += remainder as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let capacity_ratio = post_residual as f64 / bin_capacity as f64;
    let mut score = (post_residual as f64) * 1.55;

    // 1. Refined Fragmentation: Target "Golden" residuals (avoiding small slivers)
    if post_residual > 0 {
        if post_residual < 12 {
            score += 720.0 - (post_residual as f64 * 24.0);
        } else if (post_residual as f64) < (mean_residual * 0.92) {
            score -= 210.0; 
        } else if post_residual < (bin_capacity / 4) {
            score += 145.0;
        }
    }

    // 2. Predictive Lookahead: Strengthened coupling with next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let scarcity = (open_bins_count as f64) / (fitting_bins_count as f64 + 0.2);
            score -= 480.0 + (scarcity * 190.0) + (next_item_size as f64 * 7.2) + (capacity_ratio * 160.0);
        } else {
            score += 510.0 + (progress * 280.0);
        }
    }

    // 3. Dynamic Pressure: Aggressive damping on late-game, high-bin count states
    let late_game_bias = (progress.powf(2.8) * 70.0).exp() * 0.20;
    score += (open_bins_count as f64).powf(1.9) * (1.2 + late_game_bias);

    // 4. Forced Selection: High priority on single-fitting bin scenarios
    if fitting_bins_count == 1 {
        score -= 980.0;
    }

    // 5. New Bin Gate: Stricter barrier against opening new bins
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 1580.0 + (mean_residual * 14.0) + (progress * 880.0);
        } else {
            score -= 610.0; 
        }
    }

    // 6. Harmonic Alignment: Reward high-density states significantly
    if post_residual == 0 {
        score -= 1350.0;
    } else if post_residual > (bin_capacity * 82 / 100) {
        score -= 520.0; 
    } else if post_residual % 4 == 0 {
        score -= 195.0;
    }

    // 7. Uniformity: Penalize variance relative to current packing density
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += (deviation * 5.5) * (1.1 - capacity_ratio.powi(2));

    // 8. Lookahead-Residual Symmetry: Anti-deadlock for tight-fit scenarios
    if post_residual > 0 && post_residual < (next_item_size + 6) {
        score += 680.0;
    } else if post_residual == next_item_size {
        score -= 820.0;
    }

    score
}

