pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments < 10 are usually hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor keeping larger residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for blocking the next item from this bin
            score += 40.0 * (1.0 - progress);
        } else {
            // Reward for keeping space for the next item
            score -= 15.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Global state: if we have too many open bins, penalize opening new ones
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate
        score += (open_bins_count as f64 * 5.0) * (1.0 + progress);

        // If we have fitting bins, make the new bin very unattractive
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // If this bin is the last chance for this item, prioritize it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Adjust based on the global fragmentation level
    // If mean_residual is high, we are already wasting space; be more conservative
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = (post_residual as f64) * 1.74;
    let progress = step_index as f64 / total_items as f64;
    let capacity_ratio = post_residual as f64 / bin_capacity as f64;

    // 1. Refined Fragmentation Management:
    // Targeting "sliver" avoidance by heavily penalizing small residuals while rewarding mid-range compaction.
    if post_residual > 0 {
        if post_residual < 14 {
            score += 740.0 - (post_residual as f64 * 22.0);
        } else if (post_residual as f64) < (mean_residual * 0.92) {
            score -= 215.0; 
        } else if post_residual < (bin_capacity / 4) {
            score += 145.0;
        }
    }

    // 2. Predictive Lookahead:
    // Focus on pairing items with complementary sizes to minimize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let scarcity = (open_bins_count as f64) / (fitting_bins_count as f64 + 0.2);
            score -= 480.0 + (scarcity * 190.0) + (next_item_size as f64 * 7.2) + (capacity_ratio * 165.0);
        } else {
            score += 510.0 + (progress * 280.0);
        }
    }

    // 3. Dynamic Pressure Management:
    // Exponential dampening to prevent late-stream bin proliferation.
    let late_game_bias = (progress.powf(2.8) * 75.0).exp() * 0.3;
    score += (open_bins_count as f64).powf(1.9) * (1.2 + late_game_bias);

    // 4. Forced Selection Logic:
    if fitting_bins_count == 1 {
        score -= 940.0;
    }

    // 5. New Bin Gate:
    // Stricter gate to force utilization of existing bins unless the bin is near-empty.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 1520.0 + (mean_residual * 14.0) + (progress * 900.0);
        } else {
            score -= 680.0; 
        }
    }

    // 6. Harmonic Alignment:
    // Optimized for "tight" fits (near 100% capacity).
    if post_residual == 0 {
        score -= 1350.0;
    } else if post_residual > (bin_capacity * 82 / 100) {
        score -= 490.0; 
    } else if post_residual % 4 == 0 {
        score -= 210.0;
    }

    // 7. Uniformity:
    // Penalize variance relative to the global mean to maintain predictable bin levels.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += (deviation * 5.2) * (1.0 - capacity_ratio.powi(2));

    // 8. Lookahead-Residual Symmetry:
    // High penalty for creating gaps that are slightly larger than the anticipated next item (wasted potential).
    if post_residual > 0 && post_residual < (next_item_size + 6) {
        score += 680.0;
    } else if post_residual == next_item_size {
        score -= 780.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which we want to minimize (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress. 
    // As we approach the end of the stream, opening a new bin is heavily penalized.
    if is_new_bin {
        score += 25.0 + (50.0 * progress);
    } else {
        // Reward bins that are nearing exhaustion (lower post_residual is already favored),
        // but penalize creating "tiny" slivers (e.g., 1-5 units) that are hard to fill.
        if post_residual > 0 && post_residual < 8 {
            score += 15.0;
        }

        // Lookahead coupling: If next_item_size is large, favor bins that have enough space
        // to accommodate the next item (post_residual >= next_item_size).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Heuristic pressure: If this is the only bin that can fit the item, 
    // reduce the score to ensure it is picked over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Interaction with mean_residual: Favor bins that are "closer" to the current 
    // average state of open bins to keep bin utilization uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

